arguments.new_str:
protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");
        entity.HasIndex(p => p.Sku);

        // EF9 breaking change #1 — Discriminator property renamed from
        // "Discriminator" to "$type".  Existing 500K documents use the old
        // name, and direct SQL queries reference c.Discriminator, so we
        // must keep the EF8 property name.
        entity.HasDiscriminator<string>("Discriminator");

        // EF9 breaking change #2 — id values changed from
        // "Product|123" to just "123".  Existing documents already have
        // the pipe‐delimited format, so we opt back in to the EF8 scheme.
        entity.HasPartitionKey(p => p.Id);
        entity.Property(p => p.Id)
              .ToJsonProperty("id")
              .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
    });

    // Keep the EF8 id format globally for any future entities as well.
    foreach (var entityType in modelBuilder.Model.GetEntityTypes())
    {
        entityType.SetIdValueGeneratorFactory(
            (p, e) => new Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator());
    }
}

arguments.old_str:
class CosmosQuery
{
    void FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        // Also uses sync APIs
        var products = ctx.Products.Where(p => p.Sku == "ABC").ToList();
    }
}

arguments.new_str:
class CosmosQuery
{
    // EF9 breaking change #3 — Synchronous LINQ APIs (ToList, First, Single,
    // etc.) were removed for the Cosmos provider.  All queries must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references c.Discriminator, which works
        // because we preserved the old property name in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        // Use async API (ToListAsync instead of ToList)
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

